mapper.update:
UPDATE tb_address
SET consignee = #{consignee}, address_detail = #{addressDetail}, phone = #{phone}, is_default = #{isDefault}
WHERE id = #{id} and own_name = #{ownName}

mapper.select:
SELECT id, own_name AS ownName, consignee, address_detail AS addressDetail, phone, is_default AS isDefault
FROM tb_address
WHERE own_name = #{ownName}
